  ('parentalite-handicap-enfant', '1a469dd799c2e4448bd0142cb36549aa'),
  ('parentalite-voyage-enfants', 'b5295cd7a186b441bdb6fc9975e9d701'),
  ('parentalite-anniversaires', '8e69f30e5dc220ecdd5863b7964b8c70'),
  ('parentalite-loisirs-creatifs', 'f98874849b82bf097f0249837c5144f7'),
  ('parentalite-sport-famille', '7b45a913a3094e90c06cc055ab4527f5'),
  ('parentalite-grands-parents', '619eca027fcb63a61281e628b9313e40'),
  ('parentalite-adoption', '9614caf086f9c4d329f2cc74095b5807'),
  ('parentalite-pma', 'ff2d8ff39a73cda41c09c6c705b6e2e5'),
  ('parentalite-conge', 'ff201745cd0f4511def4b2052349fd40'),
  ('parentalite-budget-famille', 'cd0ae452b0fd7c009ab6dad45f243ec0'),
  ('parentalite-couple', 'f19054300b21cc45b3ac9a9d58bee3a0'),
  ('parentalite-amitie', 'bc68e908cf55130f5b9d559e894f0311'),
  ('parentalite-deuil', 'e1852c117e60b9684f6c019bef890157'),
  ('parentalite-solitude', '2b95bfbdeb9494bdbf1af4bd10a56e51'),
  ('parentalite-cuisine-enfants', '9ef5c15d13f522063dd0d010aa7e566e')
),
reel as (
  select p.id, md5(
    p.label || '|' || p.normalized_label || '|' ||
    array_to_string(p.aliases, ',') || '|' || p.is_broad::text || '|' ||
    p.popularity::text || '|' || p.sort_order::text || '|' || p.emoji || '|' || p.color
  ) as emp
  from public.passions p
)
select
  count(*) as lignes_attendues,
  count(*) filter (where r.emp is distinct from a.emp) as lignes_non_conformes,
  (select count(*) from public.passions where status = 'active') as passions_actives,
  case when count(*) filter (where r.emp is distinct from a.emp) = 0
       then 'OK' else 'ECHEC' end as verdict
  from attendu a left join reel r using (id);

commit;
